    """Return True if s is a valid IPv4 address.
    Rules:
    - Four decimal numbers separated by '.'
    - Each number 0-255 inclusive
    - No leading zeros unless the number is exactly "0"
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # non-empty, digits only
        if not part or not part.isdigit():
            return False
        # no leading zeros unless single '0'
        if len(part) > 1 and part[0] == '0':
            return False
        # value range
        try:
            val = int(part)
        except ValueError:
            return False
        if not (0 <= val <= 255):
            return False
    return True

