def solve(a, x):
    """Return the leftmost insertion index for x in sorted list a.
    Uses binary search O(log n).
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

