def solve(line):
    """Split one CSV line into fields. A comma separates fields only when
    an even number of quotes precedes it (i.e. it is not inside quotes).
    A field wrapped in a matching pair of quotes is unwrapped, with doubled
    quotes inside collapsed to one; otherwise quotes stay literal."""
    parts = []
    last = 0
    quotes = 0
    for i, ch in enumerate(line):
        if ch == '"':
            quotes += 1
        elif ch == ',' and quotes % 2 == 0:
            parts.append(line[last:i])
            last = i + 1
    parts.append(line[last:])
    out = []
    for p in parts:
        if len(p) >= 2 and p[0] == '"' and p[-1] == '"':
            out.append(p[1:-1].replace('""', '"'))
        else:
            out.append(p)
    return out

