def solve(n: int) -> int:
    """Return the number of prime numbers strictly less than n.
    Handles n <= 2 returning 0. Uses trial division for simplicity and low memory.
    """
    if n <= 2:
        return 0
    count = 0
    for num in range(2, n):
        # check primality
        is_prime = True
        if num % 2 == 0:
            if num != 2:
                is_prime = False
        else:
            # test odd divisors up to sqrt(num)
            limit = int(num ** 0.5)
            d = 3
            while d <= limit:
                if num % d == 0:
                    is_prime = False
                    break
                d += 2
        if is_prime:
            count += 1
    return count

