def solve(n):
    """Return count of primes strictly less than *n*.
    Accepts int, strings or other numeric types convertible to int.
    Non‑convertible or non‑positive values yield 0.
    """
    # Try to obtain an integer value
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    limit = n - 1
    # Sieve of Eratosthenes using bytearray for efficiency
    is_prime = bytearray(b'\x01') * (limit + 1)
    is_prime[0:2] = b'\x00\x00'  # 0 and 1 are not prime
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if is_prime[p]:
            start = p * p
            step = p
            is_prime[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(is_prime)

def solve(meetings):
    # Greedy select by earliest end time
    if not meetings:
