def solve(*args, **kwargs):
    """Return the longest palindromic substring.
    Accepts the input string as the first positional argument or as a keyword
    argument named ``s``. Extra arguments are ignored. Non‑string inputs are
    treated as empty strings.
    """
    if args:
        s = args[0]
    else:
        s = kwargs.get('s', '')
    if not isinstance(s, str):
        s = str(s) if s is not None else ''
    n = len(s)
    if n < 2:
        return s
    def expand(lo, hi):
        while lo >= 0 and hi < n and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        start = lo + 1
        length = hi - lo - 1
        return start, length
    best_start = 0
    best_len = 1
    for i in range(n):
        start, length = expand(i, i)
        if length > best_len or (length == best_len and start < best_start):
            best_start, best_len = start, length
        start, length = expand(i, i + 1)
        if length > best_len or (length == best_len and start < best_start):
            best_start, best_len = start, length
    return s[best_start:best_start + best_len]

